			}
		}

		#region RMAForOrderLine

		void AddRMAForOrderLineMenu()
		{
			var menuKey = "RMA For Order Lines"; // SuppressCodeSmell Reason = Menu Item key
			if (!LinesGrid.ContextMenu.MenuItems.ContainsKey(menuKey) && IsFinalised)
			{
				var menu = new ZMenuItem(ResString.GetMultilingualString("4075c592-332f-4377-92be-fc5de0dace61", "Generate RMA for Selected Order Lines"), RMAForOrderLineMenu_Click);
				menu.Name = menuKey;
				LinesGrid.ContextMenu.MenuItems.Add(menu);
			}
		}

		void RMAForOrderLineMenu_Click(object sender, EventArgs e)
		{
			var rmaOrder = WhsRMAOrder.GetNew((WhsOrder)Docket, LinesGrid.SelectedElements.Cast<WhsOrderLine>());
			using (var form = new RMAForOrderLinesForm(rmaOrder))
			{
				ZFormModaliser.ShowDialogWithoutDispose(form);
			}
		}

		#endregion

		#region ReduceStockMenu

		void AddReleaseLineMenuItems()
		{
			AddReduceStockMenuItem(new AdjustOutQuantityMetMenu());
			AddReduceStockMenuItem(new ReturnStockMenu());
		}

		void AddReduceStockMenuItem(ReduceStockMenu menu)
		{
			if (!LinesGrid.ContextMenu.MenuItems.ContainsKey(menu.FunctionDescription.ToString()))
			{
				var item = new ZMenuItem(menu.MenuText, delegate
				{ ReduceStock(menu); });
				LinesGrid.ContextMenu.MenuItems.Add(item);
				LinesGrid.ContextMenu.Popup += (sender, e) =>
				{
					item.Enabled = LinesGrid.SelectedElements.Length > 0 && !IsFinalised;
				};
			}
		}

		void ReduceStock(ReduceStockMenu menu)
		{
			var checkpoint = menu.PickedStockAdjustersFactory.GetAdjusterSecurityCheckpoint(menu.Reason);
			if (!checkpoint.IsAllowed)
			{
				checkpoint.ShowError();
			}
			else
			{
				var selectedElements = LinesGrid.SelectedElements;
				if (selectedElements.Length > 0)
				{
					var caption = Res.GetString("edfde08c-d88e-452f-958d-327f0b4af025", "Reduce stock");
					var message = Res.GetString("2a644ba3-fce1-44ab-bc1a-fc894bf445d1", "{0} Lines were selected. Are you sure you want to fully bulk {1}?", selectedElements.Length, menu.FunctionDescription);
					var queryEventArgs = new QueryUserYesNoEventArgs(caption, message, false);
					WhsNotificationSubscriberGuiHelper.QueryUser(queryEventArgs);
					if (queryEventArgs.Response)
					{
						ReduceStockOnOrderLines(selectedElements.Cast<WhsOrderLine>(), menu);
					}
				}
			}
		}

		[SuppressMessage("Microsoft.Design", "CA1031:DoNotCatchGeneralExceptionTypes")]
		void ReduceStockOnOrderLines(IEnumerable<WhsOrderLine> orderLines, ReduceStockMenu menu)
		{
			try
			{
				using (ZFormPostingButtonsStrategy.DeferredUpdateSaveButtonsBasedOnHasChanges((ZForm)FindForm()))
				{
					var result = ReleaseLineReductionManager.ReduceStock(orderLines, menu.PickedStockAdjustersFactory, menu.Reason);
					if (!result.IsSuccess)
					{
						Globals.Message.ShowError(result.ErrorMessage);
					}
				}
			}
			catch (Exception ex) when (!ex.IsCriticalException())
			{
				(FindForm() as ICanHandleSaveException)?.HandleException(ex);
			}
		}

