		protected override WhsDocket DocketCore
		{
			get
			{
				var result = base.DocketCore;
				if (result == null)
				{
					var pick = CurrentDataItem as WhsPick;
					if (pick != null && pick.Orders.Count > 0)
					{
						result = pick.Orders[0];
					}
				}

				return result;
			}
		}

