			ShowOrderLineEditForm((WhsOrderLine)LinesGrid.ListManager.List[LinesGrid.CurrentRowIndex]);
		}

		public void ShowOrderLineEditForm(WhsOrderLine orderLine)
		{
			if (orderLine == null)
			{
				Globals.Message.ShowWarning(Res.GetString("29bd6dd1-0772-49a3-abf1-c4038af05c47", "Please select an order line to edit."));
			}
			else if (orderLine.HasChanges)
			{
				Globals.Message.ShowWarning(Res.GetString("b2f1a37e-0612-4135-80b8-b093c72190a0", "Please save this Order before going to the Order Line Form."));
			}
			else if (orderLine.Docket.WD_DocketSubTypeInfo.HasChanges)
			{
				Globals.Message.ShowWarning(Res.GetString("878BE1D7-3AD9-4d26-9EA7-064D726425D1", "The Order Type has changed. Please save this Order before going to the Order Line Form."));
			}
			else if (orderLine.Docket.WD_WW_WhsInfo.HasChanges)
			{
				Globals.Message.ShowWarning(Res.GetString("6838A374-D924-4070-BC6D-9B44FC39F64F", "The Warehouse has changed. Please save this Order before going to the Order Line Form."));
			}
			else
			{
				var controller = ZControllerFactory.Create(ControllerIDs.WhsOrderLine);
				controller.SetFormsModalTo(this.FindForm());
				controller.ShowEditForm(orderLine);
			}
		}

